30	/* Press → one stroke-glow ring pulse. Remove+reflow+re-add restarts the CSS animation. */
31	function pulse(e: React.PointerEvent<HTMLElement>) {
32	  const el = e.currentTarget;
33	  el.classList.remove('pd-pulse');
34	  void el.offsetWidth; // force reflow so the animation restarts
35	  el.classList.add('pd-pulse');
36	}
