38	/* ── Property filter dropdown — wireframe pill + menu ── */
39	function PropertyDropdown({ options, value, onPick }: {
40	  options: string[]; value: string | null; onPick: (v: string | null) => void;
41	}) {
42	  const [open, setOpen] = useState(false);
43	  const rootRef = useRef<HTMLDivElement>(null);
44	
45	  useEffect(() => {
46	    if (!open) return;
47	    const close = (e: PointerEvent) => {
48	      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
49	    };
50	    document.addEventListener('pointerdown', close);
51	    return () => document.removeEventListener('pointerdown', close);
52	  }, [open]);
53	
54	  return (
55	    <div ref={rootRef} style={{ position: 'relative', zIndex: 20 }}>
56	      <button type="button" className="pd-tap" onPointerDown={pulse} onClick={() => setOpen(o => !o)}
57	        style={{ display: 'inline-flex', alignItems: 'center', gap: 8, padding: '8px 16px', borderRadius: 999, background: 'transparent', border: `1.5px solid ${SKY}`, color: SKY, fontWeight: 500, fontSize: 13, cursor: 'pointer', fontFamily: 'Outfit, system-ui', WebkitTapHighlightColor: 'transparent' }}>
58	        <span style={{ maxWidth: 140, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{value ?? 'all properties'}</span>
59	        <span style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s', display: 'flex' }}><IcoChev /></span>
60	      </button>
61	      {open && (
62	        <div style={{ position: 'absolute', top: 'calc(100% + 8px)', right: 0, minWidth: 200, maxHeight: 260, overflowY: 'auto', background: NAVY, border: `1.5px solid rgba(88,171,255,0.4)`, borderRadius: 16, padding: 6, boxShadow: '0 16px 40px rgba(0,0,0,0.35)' }}>
63	          {[null, ...options].map(opt => (
64	            <button key={opt ?? '__all'} type="button"
65	              onClick={() => { onPick(opt); setOpen(false); }}
66	              style={{ display: 'block', width: '100%', textAlign: 'left', padding: '10px 14px', borderRadius: 11, border: 'none', cursor: 'pointer', fontFamily: 'Outfit, system-ui', fontSize: 13, fontWeight: (value ?? null) === opt ? 700 : 400, background: (value ?? null) === opt ? 'rgba(88,171,255,0.16)' : 'transparent', color: SKY, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
67	              {opt ?? 'all properties'}
68	            </button>
69	          ))}
70	        </div>
71	      )}
72	    </div>
73	  );
74	}
