76	/* ── Timeframe selector — sliding indicator, terminal SubBar pattern ──
77	   Reports the active button's viewport center-x via onIndicator so the
78	   hero notch can follow the selection. */
79	function TimeframeBar({ tf, onPick, onIndicator }: {
80	  tf: Timeframe; onPick: (t: Timeframe) => void;
81	  onIndicator?: (centerX: number, animate: boolean) => void;
82	}) {
83	  const btnRefs = useRef<(HTMLButtonElement | null)[]>([]);
84	  const mounted = useRef(false);
85	  const [ind, setInd] = useState({ x: 0, w: 0, on: false });
86	  const [animate, setAnim] = useState(false);
87	  const activeIdx = TIMEFRAMES.indexOf(tf);
88	
89	  useEffect(() => {
90	    const tick = (anim: boolean) => {
91	      const el = btnRefs.current[activeIdx];
92	      if (!el) return;
93	      setInd({ x: el.offsetLeft, w: el.offsetWidth, on: true });
94	      const r = el.getBoundingClientRect();
95	      onIndicator?.(r.left + r.width / 2, anim);
96	    };
97	    const remeasure = () => tick(false);
98	    window.addEventListener('resize', remeasure);
99	    if (!mounted.current) {
100	      requestAnimationFrame(() => requestAnimationFrame(() => { tick(false); mounted.current = true; }));
101	      return () => window.removeEventListener('resize', remeasure);
102	    }
103	    setAnim(true);
104	    requestAnimationFrame(() => requestAnimationFrame(() => requestAnimationFrame(() => tick(true))));
105	    const t = setTimeout(() => setAnim(false), 520);
106	    return () => { clearTimeout(t); window.removeEventListener('resize', remeasure); };
107	  }, [activeIdx]);
108	
109	  return (
110	    <div style={{ display: 'flex', justifyContent: 'center' }}>
111	      <div style={{ position: 'relative', display: 'flex', alignItems: 'center', width: 'min(300px, 100%)', background: NAVY, borderRadius: 999, padding: 3, boxShadow: '0 6px 18px rgba(4,13,109,0.22)' }}>
112	        <div className={`pd-tf-ind${animate ? ' animate' : ''}`}
113	          style={{ position: 'absolute', top: 3, bottom: 3, left: ind.x, width: ind.w, borderRadius: 999, background: CYAN, opacity: ind.on ? 1 : 0 }} />
114	        {TIMEFRAMES.map((t, i) => (
115	          <button key={t} type="button" ref={el => (btnRefs.current[i] = el)}
116	            className="pd-tap" onPointerDown={pulse}
117	            onClick={() => onPick(t)}
118	            style={{ position: 'relative', zIndex: 1, flex: 1, padding: '7px 0', borderRadius: 999, border: 'none', background: 'transparent', cursor: 'pointer', fontFamily: 'Outfit, system-ui', fontWeight: tf === t ? 700 : 600, fontSize: 12, textTransform: 'capitalize', color: tf === t ? NAVY : 'rgba(88,171,255,0.55)', transition: 'color 0.25s ease', WebkitTapHighlightColor: 'transparent' }}>
119	            {t}
120	          </button>
121	        ))}
122	      </div>
123	    </div>
124	  );
125	}
126	
127	/* ── Bar chart — clickable, animates between timeframes ── */
128	const MAX_SLOTS = 12;
129	
130	function RentBarChart({ buckets, selectedIdx, onSelectBar, animKey }: {
131	  buckets: { label: string; valueCents: number }[];
132	  selectedIdx: number;
133	  onSelectBar: (i: number) => void;
134	  animKey: string;
135	}) {
136	  const W = 375, CH = 190, LABEL_H = 30, H = CH + LABEL_H, PADX = 16, BASE = CH;
137	  const n = buckets.length;
138	  const gap = n > 8 ? 10 : 24;
139	  const bw = (W - PADX * 2 - gap * (n - 1)) / n;
140	  const x = (i: number) => PADX + i * (bw + gap);
141	
142	  const [reveal, setReveal] = useState(false);
143	  useEffect(() => { const t = setTimeout(() => setReveal(true), 60); return () => clearTimeout(t); }, []);
144	
145	  const maxVal = Math.max(...buckets.map(b => b.valueCents), 1);
146	  const hOf = (v: number) => v <= 0 ? 6 : 12 + (v / maxVal) * (CH - 40);
147	
148	  const sel = buckets[selectedIdx];
149	  const selX = x(Math.min(selectedIdx, n - 1)) + bw / 2;
150	  const selTop = BASE - hOf(sel?.valueCents ?? 0);
151	
152	  return (
153	    <div style={{ position: 'relative', margin: '22px -6px 0' }}>
154	      <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: 'block', height: 'auto', overflow: 'visible' }}>
155	        {Array.from({ length: MAX_SLOTS }, (_, i) => {
156	          const active = i < n;
157	          const bh = active && reveal ? hOf(buckets[i].valueCents) : 0;
158	          const bx = active ? x(i) : W - PADX - bw;
159	          return (
160	            <rect key={i} className="pd-bar"
161	              x={bx} width={Math.max(bw, 1)}
162	              y={BASE - bh} height={bh}
163	              rx={bw / 2}
164	              fill={i === selectedIdx ? SEL : BAR}
165	              style={{ cursor: active ? 'pointer' : 'default', pointerEvents: active ? 'auto' : 'none' }}
166	              onClick={() => active && onSelectBar(i)}
167	            />
168	          );
169	        })}
170	        {buckets.map((b, i) => (
171	          <text key={`${animKey}-${i}`} className="pd-bar-label"
172	            x={x(i) + bw / 2} y={CH + 22} textAnchor="middle"
173	            fontFamily="Outfit, system-ui" fontWeight="600" fontSize={n > 8 ? 11 : 13} fill={SKY}>
174	            {b.label}
175	          </text>
176	        ))}
177	      </svg>
178	      {/* Value pill above the selected bar */}
179	      {sel && (
180	        <div key={`${animKey}-${selectedIdx}`} className="pd-bar-pill"
181	          style={{ position: 'absolute', left: `${(selX / W) * 100}%`, top: `${(selTop / H) * 100}%`, transform: 'translate(-50%, calc(-100% - 8px))', background: SEL, color: NAVY, padding: '5px 14px', borderRadius: 999, fontWeight: 700, fontSize: 13, whiteSpace: 'nowrap', boxShadow: '0 6px 16px rgba(0,127,255,0.35)', pointerEvents: 'none' }}>
182	          {fmtCompact(sel.valueCents)}
183	        </div>
184	      )}
185	    </div>
186	  );
187	}
