189	export default function PropertyDashboard() {
190	  const [, setLocation] = useLocation();
191	  const [tf, setTf] = useState<Timeframe>('week');
192	  const [propFilter, setPropFilter] = useState<string | null>(null);
193	  const [selBar, setSelBar] = useState(-1); // -1 → default to last bucket
194	  const colRef = useRef<HTMLDivElement>(null);
195	  const [notch, setNotch] = useState<{ x: number; anim: boolean } | null>(null);
196	
197	  // Notch follows the active timeframe button (x is relative to the column).
198	  const handleIndicator = (centerX: number, anim: boolean) => {
199	    const col = colRef.current?.getBoundingClientRect();
200	    if (col) setNotch({ x: centerX - col.left, anim });
201	  };
202	
203	  const { data: tenants = [] } = useQuery<any[]>({
204	    queryKey: ['/api/property/tenants'],
205	    queryFn: () => propFetch('/api/property/tenants').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
206	    staleTime: 60000, retry: false,
207	  });
208	
209	  const { data: invoices = [], isLoading: invLoading, isError: invError, refetch: refetchInv } = useQuery<any[]>({
210	    queryKey: ['/api/property/invoices'],
211	    queryFn: () => propFetch('/api/property/invoices').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
212	    staleTime: 30000, retry: false,
213	  });
214	
215	  /* Portfolio filter, then all figures derive from the filtered sets */
216	  const addresses = Array.from(new Set(tenants.map((t: any) => t.propertyAddress).filter(Boolean))) as string[];
