286	        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.15fr', gap: 14, padding: '26px 22px 0' }}>
287	          <button type="button" className="pd-card pd-tap" onPointerDown={pulse} onClick={() => setLocation('/property/tenants')}
288	            style={{ background: '#FFFFFF', borderRadius: 22, padding: '16px 18px', border: 'none', cursor: 'pointer', textAlign: 'left', fontFamily: 'Outfit, system-ui' }}>
289	            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 6 }}>
290	              <div style={{ fontWeight: 700, fontSize: 11, color: NAVY, letterSpacing: '0.08em', textTransform: 'uppercase' }}>tenants</div>
291	              <IcoPeeps />
292	            </div>
293	            <div style={{ marginTop: 10, fontWeight: 800, fontSize: 42, color: NAVY, letterSpacing: '-0.03em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>{activeTenants}</div>
294	          </button>
295	          <button type="button" className="pd-card pd-tap" onPointerDown={pulse} onClick={() => setLocation('/property/terminal?stack=overdue')}
296	            style={{ background: NAVY, borderRadius: 22, padding: '16px 18px', border: 'none', cursor: 'pointer', textAlign: 'left', fontFamily: 'Outfit, system-ui' }}>
297	            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 6 }}>
298	              <div style={{ fontWeight: 700, fontSize: 11, color: SKY, letterSpacing: '0.08em', textTransform: 'uppercase' }}>outstanding</div>
