301	            <div style={{ marginTop: 10, fontWeight: 800, fontSize: 42, color: SKY, letterSpacing: '-0.03em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>{overdueCount}</div>
302	          </button>
303	        </div>
304	
305	        {/* ── Action shortcuts ── */}
306	        <div style={{ display: 'grid', gridTemplateColumns: '1.25fr 1fr 1fr', gap: 12, padding: '18px 22px 0' }}>
307	          {[
308	            { label: <>set up<br />rent payment</>, Ico: IcoPlus, to: '/property/terminal?screen=tenants', aria: 'set up rent payment' },
309	            { label: <>send<br />reminder</>, Ico: IcoBell, to: '/property/terminal?stack=overdue&remind=1', aria: 'send reminder' },
310	            { label: <>send<br />expense</>, Ico: IcoBill, to: '/property/terminal?screen=bill', aria: 'send expense' },
311	          ].map(({ label, Ico, to, aria }) => (
312	            <button key={aria} type="button" className="pd-card pd-tap" aria-label={aria}
313	              onPointerDown={pulse} onClick={() => setLocation(to)}
314	              style={{ background: '#FFFFFF', borderRadius: 18, padding: '14px 14px 12px', border: 'none', cursor: 'pointer', textAlign: 'left', fontFamily: 'Outfit, system-ui', display: 'flex', flexDirection: 'column', gap: 14, minHeight: 88 }}>
