330	.pd-bar-label { animation: pdFadeIn 0.5s ease 0.25s both; }
331	.pd-bar-pill { animation: pdPillIn 0.35s cubic-bezier(0.34,1.56,0.64,1) 0.2s both; }
332	@keyframes pdFadeIn { from { opacity: 0; } to { opacity: 1; } }
333	@keyframes pdPillIn { from { opacity: 0; transform: translate(-50%, calc(-100% - 2px)) scale(0.85); } to { opacity: 1; transform: translate(-50%, calc(-100% - 8px)) scale(1); } }
334	.pd-card { box-shadow: 0 4px 14px rgba(4,13,109,0.08); transition: transform 0.18s ease, box-shadow 0.18s ease; -webkit-tap-highlight-color: transparent; }
335	.pd-card:hover { transform: translateY(-1px); box-shadow: 0 8px 22px rgba(4,13,109,0.14); }
