15	function SemiCircularProgress({ percentage, size, strokeWidth, color, backgroundColor = 'rgba(255,255,255,0.1)' }: CircularProgressProps) {
16	  const radius = (size - strokeWidth) / 2;
17	  const circumference = radius * Math.PI;
18	  const offset = circumference - (percentage / 100) * circumference;
19	
20	  return (
21	    <svg width={size} height={size / 2 + strokeWidth} className="overflow-visible">
22	      <path
23	        d={`M ${strokeWidth / 2} ${size / 2} A ${radius} ${radius} 0 0 1 ${size - strokeWidth / 2} ${size / 2}`}
24	        stroke={backgroundColor}
25	        strokeWidth={strokeWidth}
26	        fill="none"
27	        strokeLinecap="round"
28	      />
29	      <path
