85	/* ── Stat icon SVGs (off-white on the dark stat tiles) ── */
86	function IcoClients({ c }: { c: string }) {
87	  return <svg width={17} height={17} viewBox="0 0 24 24" fill={c}><circle cx="8.5" cy="8" r="3"/><circle cx="16" cy="8.5" r="2.4"/><path d="M2.6 19c0-3.2 2.6-5.6 5.9-5.6s5.9 2.4 5.9 5.6z"/><path d="M15.4 13.6c2.6.2 4.9 2.3 4.9 5.1"/></svg>;
88	}
